package main

import (
	"encoding/json"
	"path/filepath"
	"strings"
	"testing"
)

// The authentic plans live in testdata/plans/<engine>/, generated by scripts/gen-plans.sh.
var engines = []string{"terraform", "opentofu"}

// realPlanPath returns the absolute path of the plan of a scenario for an engine.
func realPlanPath(t *testing.T, engine, scenario string) string {
	t.Helper()
	return fixturePath(t, engine+"/"+scenario+".json")
}

// Scenarios both engines plan and the parser reads as exported, with their counted changes.
var cliReadablePlans = []struct {
	name  string
	total int
}{
	{"create-before-destroy", 1},
	{"empty-config", 0},
	{"forced-replace", 2},
	{"import", 1},
	{"moved", 1},
	{"no-changes", 0},
}

// Plans rejected today because of boolean sensitivity flags: every plan that creates or deletes a
// resource, including those made with real providers.
var cliRejectedPlans = map[string][]string{
	"terraform": {
		"count-for-each", "data-source", "destroy-all", "mixed-actions", "nested-modules", "sensitive",
		"provider-random", "provider-multi-create", "provider-multi-actions", "provider-nested-blocks",
		"provider-sensitive",
	},
	"opentofu": {
		"count-for-each", "data-source", "destroy-all", "mixed-actions", "nested-modules", "sensitive",
		"provider-random", "opentofu-provider-for-each",
	},
}

// Every authentic plan must be either readable or listed as rejected, so a new scenario cannot
// silently escape the end-to-end tests.
func TestRealPlans_AllListed(t *testing.T) {
	for _, engine := range engines {
		listed := map[string]bool{}
		for _, rp := range cliReadablePlans {
			listed[rp.name] = true
		}
		for _, name := range cliRejectedPlans[engine] {
			listed[name] = true
		}

		files, err := filepath.Glob(filepath.Join(filepath.Dir(realPlanPath(t, engine, "empty-config")), "*.json"))
		if err != nil {
			t.Fatalf("glob: %v", err)
		}
		if len(files) != len(listed) {
			t.Errorf("%s: %d plans on disk, %d listed", engine, len(files), len(listed))
		}
		for _, f := range files {
			if name := strings.TrimSuffix(filepath.Base(f), ".json"); !listed[name] {
				t.Errorf("%s/%s is neither readable nor listed as rejected", engine, name)
			}
		}
	}
}

func TestRealPlans_AllFormats(t *testing.T) {
	for _, engine := range engines {
		for _, rp := range cliReadablePlans {
			for _, format := range []string{"markdown", "text", "json"} {
				t.Run(engine+"/"+rp.name+"/"+format, func(t *testing.T) {
					res := runCLI(t, cliOpts{Args: []string{"-p", realPlanPath(t, engine, rp.name), "-f", format}})
					if res.Code != 0 {
						t.Fatalf("exit code = %d, want 0\nstderr: %s", res.Code, res.Stderr)
					}
					if strings.TrimSpace(res.Stdout) == "" {
						t.Fatalf("empty report")
					}

					if format == "json" {
						var rep struct {
							Summary struct {
								TotalChanges int `json:"total_changes"`
							} `json:"summary"`
							Changes []json.RawMessage `json:"changes"`
						}
						if err := json.Unmarshal([]byte(res.Stdout), &rep); err != nil {
							t.Fatalf("stdout is not valid JSON: %v", err)
						}
						if rep.Summary.TotalChanges != rp.total || len(rep.Changes) != rp.total {
							t.Errorf("total_changes/changes = %d/%d, want %d", rep.Summary.TotalChanges, len(rep.Changes), rp.total)
						}
						return
					}
					if rp.total == 0 && !strings.Contains(strings.ToLower(res.Stdout), "no changes") {
						t.Errorf("report does not say there are no changes:\n%s", res.Stdout)
					}
				})
			}
		}
	}
}

func TestRealPlans_VersionShown(t *testing.T) {
	for engine, version := range map[string]string{"terraform": "1.10.5", "opentofu": "1.9.0"} {
		t.Run(engine, func(t *testing.T) {
			res := runCLI(t, cliOpts{Args: []string{"-p", realPlanPath(t, engine, "forced-replace")}})
			if want := "**Terraform Version:** " + version; !strings.Contains(res.Stdout, want) {
				t.Errorf("report does not contain %q:\n%s", want, res.Stdout)
			}
		})
	}
}

func TestRealPlans_Filters(t *testing.T) {
	for _, engine := range engines {
		plan := realPlanPath(t, engine, "forced-replace")

		t.Run(engine+"/replace action keeps both replacements", func(t *testing.T) {
			res := runCLI(t, cliOpts{Args: []string{"-p", plan, "-a", "replace"}})
			if res.Code != 0 || !strings.Contains(res.Stdout, "**Total Changes:** 2") {
				t.Errorf("code=%d, want 0 and 2 changes\n%s%s", res.Code, res.Stdout, res.Stderr)
			}
		})

		t.Run(engine+"/create action matches nothing", func(t *testing.T) {
			res := runCLI(t, cliOpts{Args: []string{"-p", plan, "-a", "create"}})
			if res.Code != 0 || !strings.Contains(strings.ToLower(res.Stdout), "no changes") {
				t.Errorf("code=%d, want 0 and a no-changes report\n%s%s", res.Code, res.Stdout, res.Stderr)
			}
		})

		t.Run(engine+"/unknown type matches nothing", func(t *testing.T) {
			res := runCLI(t, cliOpts{Args: []string{"-p", plan, "-t", "aws_instance"}})
			if res.Code != 0 || !strings.Contains(strings.ToLower(res.Stdout), "no changes") {
				t.Errorf("code=%d, want 0 and a no-changes report\n%s%s", res.Code, res.Stdout, res.Stderr)
			}
		})

		t.Run(engine+"/no-op resources never appear", func(t *testing.T) {
			res := runCLI(t, cliOpts{Args: []string{"-p", plan}})
			if strings.Contains(res.Stdout, "untouched") {
				t.Errorf("the no-op resource is listed:\n%s", res.Stdout)
			}
			for _, name := range []string{"requested", "tainted"} {
				if !strings.Contains(res.Stdout, "`"+name+"`") {
					t.Errorf("replaced resource %q is missing:\n%s", name, res.Stdout)
				}
			}
		})
	}
}

// FR-013: no attribute value from the plan is ever written. Plans with sensitive values are rejected
// today (see the known gap below), so the check runs on every readable plan.
func TestRealPlans_NoAttributeValues(t *testing.T) {
	for _, engine := range engines {
		for _, rp := range cliReadablePlans {
			t.Run(engine+"/"+rp.name, func(t *testing.T) {
				res := runCLI(t, cliOpts{Args: []string{"-p", realPlanPath(t, engine, rp.name), "-f", "json"}})
				for _, leaked := range []string{"SYNTHETIC-SECRET", `"before"`, `"after"`, `"input"`, `"triggers_replace"`} {
					if strings.Contains(res.Stdout, leaked) {
						t.Errorf("report contains %q", leaked)
					}
				}
			})
		}
	}
}

// PROVISIONAL: pins Known Gap "A plan in the exact shape Terraform exports is rejected"
// (specs/001-baseline-cli-behavior/spec.md). Update deliberately when the gap is fixed.
func TestKnownGap_RealPlansRejectedByCLI(t *testing.T) {
	for engine, scenarios := range cliRejectedPlans {
		for _, name := range scenarios {
			t.Run(engine+"/"+name, func(t *testing.T) {
				res := runCLI(t, cliOpts{Args: []string{"-p", realPlanPath(t, engine, name)}})
				if res.Code != 1 {
					t.Errorf("exit code = %d, want 1 (the plan is rejected); the gap seems fixed, update this test", res.Code)
				}
				if !strings.Contains(res.Stderr, "failed to parse plan:") {
					t.Errorf("stderr = %q, want a parse failure", res.Stderr)
				}
			})
		}
	}
}
